            .arg(Arg::new("all-features").long("all-features").action(ArgAction::SetTrue).help("Run the check for all features instead of the current active ones only"))
            .arg(Arg::new("path").help("The path of a file or directory to check availability")))
        .subcommand(Command::new("clean").about("Remove artifacts from the target directory"))
        .subcommand(Command::new("toolchain").about("Install or uninstall the toolchain")
            .subcommand(Command::new("install").about("Install the toolchain")
                .arg(Arg::new("path").long("path").value_name("path").help("Runtime directory path to install RustOwl toolchain"))
                .arg(Arg::new("skip").long("skip-rustowl-toolchain").action(ArgAction::SetTrue).help("Install Rust toolchain only")))
            .subcommand(Command::new("uninstall").about("Uninstall the toolchain")))
        .subcommand(Command::new("completions").about("Generate shell completions")
            .arg(Arg::new("SHELL").help("The shell to generate completions for").value_parser(["bash","elvish","fish","powershell","zsh","nushell"]).required(true)))
}
fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() == 3 && args[1]=="completions" {
        let mut cmd = cli();
        let shell = args[2].as_str();
        let mut buf = BufWriter::new(std::io::stdout());
        match shell {
            "bash" => generate(Bash, &mut cmd, "rustowl", &mut buf),
            "elvish" => generate(Elvish, &mut cmd, "rustowl", &mut buf),
            "fish" => generate(Fish, &mut cmd, "rustowl", &mut buf),
            "powershell" => generate(PowerShell, &mut cmd, "rustowl", &mut buf),
            "zsh" => generate(Zsh, &mut cmd, "rustowl", &mut buf),
            "nushell" => generate(Nushell, &mut cmd, "rustowl", &mut buf),
            _ => {},
        }
        use std::io::Write;
        buf.flush().unwrap();
        return;
    }
    let cmd = cli();
    match cmd.try_get_matches() {
        Ok(m) => println!("OK {:?}", m),
        Err(e) => { e.print().unwrap(); std::process::exit(e.exit_code()); }
    }
}
