                try:
                    return urllib.parse.unquote(uri[7:])
                except:
                    return uri[7:]
    return None'''
new_extract = '''def parse_file_uri(uri):
    # uri is string starting with file://, return file path string
    # handle file://localhost/tmp -> /tmp, file:///tmp -> /tmp, file:// -> /
    try:
        parsed = urllib.parse.urlparse(uri)
        # parsed.path is path part, netloc is host
        path = parsed.path
        if not path:
            path = "/"
        return urllib.parse.unquote(path)
    except:
        # fallback to simple strip
        return urllib.parse.unquote(uri[7:] if len(uri) >= 7 else "/")

def extract_workspace(params):
    # returns (path_or_None, error_response_or_None)
    # error_response is tuple (code, message) to send if invalid uri
    # For valid file://, return path; for https:// etc. with :// but not file://, return None (no workspace, no error)
    # For relative (no ://), return error
    if not isinstance(params, dict):
        return None, None
    # check rootUri first
    if "rootUri" in params:
        root = params["rootUri"]
        if root is None:
            pass
        elif isinstance(root, str):
            if root.startswith("file://"):
                return parse_file_uri(root), None
            elif "://" in root:
                # e.g., https:// -> treat as no workspace
                return None, None
            else:
                # relative URL
                return None, (-32602, f'relative URL without a base: {json.dumps(root)}')
        else:
            # invalid type for rootUri
            if isinstance(root, bool):
                return None, (-32602, f"invalid type: boolean `{str(root).lower()}`, expected a string representing an URL")
            elif isinstance(root, int):
                return None, (-32602, f"invalid type: integer `{root}`, expected a string representing an URL")
            elif isinstance(root, dict):
                return None, (-32602, "invalid type: map, expected a string representing an URL")
            elif isinstance(root, list):
                return None, (-32602, "invalid type: sequence, expected a string representing an URL")
            else:
                return None, (-32602, "invalid type: expected a string representing an URL")
    # check workspaceFolders
    if "workspaceFolders" in params:
        wf = params["workspaceFolders"]
        if wf is None:
            return None, None
        if not isinstance(wf, list):
            if isinstance(wf, str):
                return None, (-32602, f'invalid type: string {json.dumps(wf)}, expected a sequence')
            elif isinstance(wf, bool):
                return None, (-32602, f"invalid type: boolean `{str(wf).lower()}`, expected a sequence")
            elif isinstance(wf, int):
                return None, (-32602, f"invalid type: integer `{wf}`, expected a sequence")
            elif isinstance(wf, dict):
                return None, (-32602, "invalid type: map, expected a sequence")
            else:
                return None, (-32602, "invalid type: expected a sequence")
        if len(wf) == 0:
            return None, None
        # check first element? Original likely checks all? For simplicity, check first.
        # If any element invalid, return error for that? We'll check first only.
        first = wf[0]
        if isinstance(first, dict):
            uri = first.get("uri")
            if isinstance(uri, str):
                if uri.startswith("file://"):
                    return parse_file_uri(uri), None
                elif "://" in uri:
                    return None, None
                else:
                    return None, (-32602, f'relative URL without a base: {json.dumps(uri)}')
            elif uri is None:
                return None, None
            else:
                if isinstance(uri, bool):
                    return None, (-32602, f"invalid type: boolean `{str(uri).lower()}`, expected a string representing an URL")
                elif isinstance(uri, int):
                    return None, (-32602, f"invalid type: integer `{uri}`, expected a string representing an URL")
                elif isinstance(uri, dict):
                    return None, (-32602, "invalid type: map, expected a string representing an URL")
                elif isinstance(uri, list):
                    return None, (-32602, "invalid type: sequence, expected a string representing an URL")
                else:
                    return None, (-32602, "invalid type: expected a string representing an URL")
        else:
            # first not dict? Unclear. Treat as no workspace?
            return None, None
    return None, None'''
if old_extract in p:
    p=p.replace(old_extract, new_extract)
    pathlib.Path("/workspace/main.py").write_text(p)
    print("patched extract")
else:
    print("not found extract")
