import subprocess, json
def one(uri):
    msg={"jsonrpc":"2.0","id":1,"method":"initialize","params":{"processId":None,"capabilities":{},"rootUri":uri}}
    b=json.dumps(msg).encode()
    p=f"Content-Length: {len(b)}\r\n\r\n".encode()+b
    for exe in ["/workspace/executable","/tmp/executable"]:
        r=subprocess.run([exe],cwd="/workspace",capture_output=True,timeout=10,input=p)
        print(f"{exe} uri={uri!r} out={r.stdout!r} err={r.stderr[:600]!r}")
    print()
for uri in ["", "foo", "/tmp", 123, True, "file://localhost/tmp", "https://example.com", "file:///tmp/%20space"]:
    one(uri)
